import{_ as d,C as n,o as s,c as e,j as i,E as r,a as l,a3 as o}from"./chunks/framework.C6R8kWFE.js";const z=JSON.parse('{"title":"2-hafta (Mentor)","description":"","frontmatter":{"title":"2-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (IoT)","link":"/mentor/9-sinf-iot/"},"n":2,"bob":"I-bob · IoT asoslari va virtual laboratoriya","lessons":[{"g":4,"title":"4-dars: Tinkercad.com virtual laboratoriyasida ro‘yxatdan o‘tish va interfeys","lead":"Tinkercad.com virtual laboratoriyasida ro‘yxatdan o‘tish va interfeys","link":"/mentor/9-sinf-iot/hafta-02/dars-1","slide":"/slaydlar/9-sinf-iot/hafta-02/dars-1.html","test":"/slaydlar/9-sinf-iot/hafta-02/dars-1-test.html"},{"g":5,"title":"5-dars: Tinkercad muhitida virtual elektron komponentlar bilan ishlash","lead":"Tinkercad muhitida virtual elektron komponentlar bilan ishlash","link":"/mentor/9-sinf-iot/hafta-02/dars-2","slide":"/slaydlar/9-sinf-iot/hafta-02/dars-2.html","test":"/slaydlar/9-sinf-iot/hafta-02/dars-2-test.html"},{"g":6,"title":"6-dars: Elektron sxema asosida bitta LED lampaning ishlash prinsipi va ulanishi","lead":"Elektron sxema asosida bitta LED lampaning ishlash prinsipi va ulanishi","link":"/mentor/9-sinf-iot/hafta-02/dars-3","slide":"/slaydlar/9-sinf-iot/hafta-02/dars-3.html","test":"/slaydlar/9-sinf-iot/hafta-02/dars-3-test.html"}],"test":"/slaydlar/9-sinf-iot/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-iot/hafta-02/index.md","filePath":"mentor/9-sinf-iot/hafta-02/index.md"}'),h={name:"mentor/9-sinf-iot/hafta-02/index.md"},u={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},c={class:"blk"},g={id:"baholash-mezoni",tabindex:"-1"};function b(k,a,v,y,q,f){const t=n("Icon");return s(),e("div",null,[i("div",u,[i("h2",m,[r(t,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_4-dars-tinkercad-com-virtual-laboratoriyasida-ro-yxatdan-o-tish-va-interfeys" tabindex="-1">4-dars: Tinkercad.com virtual laboratoriyasida ro‘yxatdan o‘tish va interfeys <a class="header-anchor" href="#_4-dars-tinkercad-com-virtual-laboratoriyasida-ro-yxatdan-o-tish-va-interfeys" aria-label="Permalink to &quot;4-dars: Tinkercad.com virtual laboratoriyasida ro‘yxatdan o‘tish va interfeys&quot;">​</a></h2><ol><li>Tinkercad.com saytidagi shaxsiy profilingizga kiring va &quot;Circuits&quot; bo&#39;limida yangi loyiha yarating. Unga <code>9-sinf_UygaVazifa_4</code> nomini bering.</li><li>Ish maydoniga kamida 4 ta turli komponentni joylashtiring (masalan: Arduino Uno, kichik Breadboard, LED, 9V batareya).</li><li>&quot;Rotate&quot; (R) asbobi yordamida breadboardni 90 gradusga buring, &quot;Notes&quot; (N) asbobi yordamida har bir komponent yoniga uning vazifasini bildiruvchi matnli yorliq biriktiring.</li><li>&quot;Send To&quot; / &quot;Share&quot; orqali sxemangizning ommaviy havolasini (Public Share link) oling va havola to&#39;g&#39;ri ochilayotganini tekshiring.</li></ol><hr><h2 id="_5-dars-tinkercad-muhitida-virtual-elektron-komponentlar-bilan-ishlash" tabindex="-1">5-dars: Tinkercad muhitida virtual elektron komponentlar bilan ishlash <a class="header-anchor" href="#_5-dars-tinkercad-muhitida-virtual-elektron-komponentlar-bilan-ishlash" aria-label="Permalink to &quot;5-dars: Tinkercad muhitida virtual elektron komponentlar bilan ishlash&quot;">​</a></h2><ol><li>Breadboard ustida 9V batareya, suriluvchi kalit (Slide switch), 330 Om rezistor va sariq LED dan iborat mustaqil yopiq elektr zanjirini yig&#39;ing.</li><li>Zanjirga virtual multimetrni &quot;Voltage&quot; rejimida ulab, sariq LED uchlaridagi kuchlanish tushuvini (Volt) o&#39;lchang.</li><li>Ikkinchi multimetrni &quot;Amperage&quot; rejimida zanjirga ketma-ket ulab, zanjirdan o&#39;tayotgan tok kuchini (milliAmper — mA) aniqlang.</li><li>Rezistor qiymatini 1 kOm ga oshiring va tok kuchi hamda yorug&#39;lik intensivligi qanday o&#39;zgarganini 2 ta jumla bilan tahlil qiling.</li></ol><hr><h2 id="_6-dars-elektron-sxema-asosida-bitta-led-lampaning-ishlash-prinsipi-va-ulanishi" tabindex="-1">6-dars: Elektron sxema asosida bitta LED lampaning ishlash prinsipi va ulanishi <a class="header-anchor" href="#_6-dars-elektron-sxema-asosida-bitta-led-lampaning-ishlash-prinsipi-va-ulanishi" aria-label="Permalink to &quot;6-dars: Elektron sxema asosida bitta LED lampaning ishlash prinsipi va ulanishi&quot;">​</a></h2><ol><li>Arduino Uno platasining <code>D9</code> raqamli piniga 220 Om rezistor orqali bitta qizil LED ni ulang va katodini Arduino <code>GND</code> ga bog&#39;lang.</li><li>Tinkercad &quot;Code&quot; panelida C++ tilida quyidagi mantiqqa ega dastur yozing: <ul><li>LED 1 soniya yonsin;</li><li>500 millisekund o&#39;chsin;</li><li>LED 2 soniya yonsin;</li><li>1 soniya o&#39;chsin;</li><li>Tsikl cheksiz takrorlansin.</li></ul></li><li>Nima uchun 5V quvvatda ishlaydigan Arduino uchun 220 Om rezistor tanlanganini Om qonuni formulasi ($R = (5\\text{V} - 2\\text{V}) / 0.015\\text{A}$) asosida yozma asoslab bering.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>4-dars vazifasi (30 ball):</strong> Tinkercad akkaunti to&#39;g&#39;ri ochilgani, loyiha nomlangani, asboblar (R, N) qo&#39;llangani va ommaviy havola taqdim etilgani.</li><li><strong>5-dars vazifasi (35 ball):</strong> Breadboard ichki kontaktlari to&#39;g&#39;ri tushunilgani, kalit va rezistor to&#39;g&#39;ri ulangani, multimetr voltmetr (parallel) va ampermetr (ketma-ket) rejimida to&#39;g&#39;ri ko&#39;rsatkich bergani.</li><li><strong>6-dars vazifasi (35 ball):</strong> Arduino 9-piniga to&#39;g&#39;ri sxema yig&#39;ilgani, C++ tilida <code>setup()</code> va <code>loop()</code> arxitekturasi buzilmasdan vaqt intervallari to&#39;g&#39;ri kodlangani hamda Om qonuni hisobi keltirilgani.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>O&#39;quvchilar rezistor oyoqlarini bitta ustunga suqib qo&#39;ymasligiga va kod yozishda <code>pinMode(LED, OUTPUT)</code> buyrug&#39;ini tushirib qoldirmasligiga e&#39;tibor qarating.</li></ul>',16))]),i("div",c,[i("h2",g,[r(t,{name:"list-checks"}),a[3]||(a[3]=l(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p><strong>Mavzular:</strong></p><ol><li>Tinkercad.com virtual laboratoriyasida ro‘yxatdan o‘tish va interfeys</li><li>Tinkercad muhitida virtual elektron komponentlar bilan ishlash: Breadboard, rezistor, LED, batareyalar, multimetr</li><li>Elektron sxema asosida bitta LED lampaning ishlash prinsipi va ulanishi: Arduino Uno, GPIO, Om qonuni, C++ Blink kodi</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Tinkercad Interfeysi va Sozlamalar</strong></td><td>Akkaunt ochish, Circuits loyihasini nomlash, Workplane asboblari (Rotate, Delete, Notes), Basic/All kutubxonasi, Share havolasi</td><td>30 ball</td></tr><tr><td><strong>Virtual Komponentlar va Multimetr</strong></td><td>Breadboard ichki ulanishi (quvvat shinalari va vertikal ustunlar), rezistor rang kodlari, LED (Anod/Katod), multimetr bilan kuchlanish va tokni o&#39;lchash</td><td>35 ball</td></tr><tr><td><strong>Arduino Uno va Dasturlash (Blink)</strong></td><td>Arduino 9-piniga to&#39;g&#39;ri sxema yig&#39;ish, Om qonuni bo&#39;yicha 220 Om rezistor hisobi, <code>setup()</code> va <code>loop()</code>, <code>pinMode()</code>, <code>digitalWrite()</code>, <code>delay()</code> kodini yozish</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Tinkercad Interfeysi (30)</th><th>Komponentlar &amp; O&#39;lchash (35)</th><th>Arduino &amp; Dasturlash (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar ko&#39;pincha rezistor yoki LED ning ikkala oyog&#39;ini bitta 5 talik vertikal qatorga ulab, qisqa tutashuv hosil qilishadi. Shuningdek, dasturlashda <code>pinMode()</code> e&#39;lon qilinmasa, pin sukut bo&#39;yicha kirish (INPUT) rejimida qolib, LED xira yonishi kabi xatolarga duch kelishadi. Bu holatlarni dars davomida ko&#39;rgazmali tushuntirish muhim.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> Arduino Uno ning bir nechta pinlariga turli rangdagi LEDlarni ulab, Morze alifbosi yoki har xil miltillash animatsiyalarini yaratish, shuningdek multimetr orqali turli rangdagi LEDlarning ochilish kuchlanishlarini amalda o&#39;lchash topshirig&#39;i berilishi mumkin.</li></ul>',11))])])}const x=d(h,[["render",b]]);export{z as __pageData,x as default};
